package com.deepanshuraj.opspilot.agent; import java.util.*; import java.util.concurrent.*; import org.springframework.stereotype.Component;
@Component public class ConversationMemory {private final Map<String,Deque<String>> sessions=new ConcurrentHashMap<>(); public void add(String s,String role,String text){Deque<String>d=sessions.computeIfAbsent(s,x->new ArrayDeque<>());synchronized(d){d.addLast(role+": "+text);while(d.size()>6)d.removeFirst();}}public List<String> history(String s){Deque<String>d=sessions.get(s);if(d==null)return List.of();synchronized(d){return List.copyOf(d);}}}
